branches.transform:
$state.context.(

  $isZero := function($n) {
    $round($abs($n), 15) = 0
  };

  /* We can safely assume that all weight units are the same here (including existing)
     so checking one is the same as checking all of them.
     If one doesn't exist, we don't need to check for any of them. */
  $exists(sourceInventory.netWeight.unitId)
  and
  (
    $allWeightValues := [
      sourceInventory.netWeight.value,
      sourceInventory.grossWeight.value,
      destinationInventory.netWeight.value,
      destinationInventory.grossWeight.value
    ];

    /* If all are zero, that's ok. It's only a problem when some are and some aren't. */
    $any($allWeightValues, $isZero)
    and $not($all($allWeightValues), $isZero)
  )
)

