    "data": {
      "Source Inventory Quantity": sourceInventory.($string(quantity.value) & " " & quantity.unit.code),
      "Source Inventory Net Weight": sourceInventory.($string(netWeight.value) & " " & netWeight.unit.code),
      "Source Inventory Weight Ratio": sourceInventory.($string($sourceDensity) & " " & netWeight.unit.code & "/" & quantity.unit.code),
