      "Destination Inventory Weight Ratio": destinationInventory.($string($sourceDensity) & " " & netWeight.unit.code & "/" & quantity.unit.code),
      "Weight Ratio Error": $formatNumber($symmetricDifference($sourceDensity, $destinationDensity), "0.00%"),
      "context": input.debugMode ? $state.context,
      "payload": input.debugMode ? $$
    }
  };
)

