      },
      "where": {
        "id": sourceInventory.id
      }
    },

    "destinationPayload": {
      "update": {
        "quantity": { "value": destinationInventory.quantity.value + mergeQty.value },
        "lastTransactionTypeId": "inventoryMerge"
      },
      "where": {
        "id": destinationInventory.id
      }
    }
  }
)

