  unit(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        unitTypeId
        unitType {
          id
          label
          description
        }
        name
        code
        conversions {
          edges {
            node {
              id
              sourceUnitId
