          }
        }
      }
    }
  }
}

query Inventory($whereSource: InventoryWhereInput, $whereDestination: InventoryWhereInput) {
  sourceInventory: inventory(where: $whereSource) {
    edges { node { id } }
  }

  destinationInventory: inventory(where: $whereDestination) {
    edges { node { id } }
  }
}

